import assert from 'node:assert/strict';
import test from 'node:test';
import { parseChatImport } from '../src/main/chatImports/parsers';

// Synthetic fixtures only. Response item/content unions were checked against TypeScript
// generated by the installed Codex app-server; Claude Code's installed transcript writer
// confirms uuid/parentUuid/sessionId/isSidechain/timestamp and message.role/content blocks.
const at = '2026-09-26T12:00:00Z';
const later = '2026-09-26T12:01:00Z';
const plain = (value: string) => ({ type: 'text', text: value });
const call = (id = 'call-1', name = 'read_file') => ({ type: 'tool_use', id, name, input: { path: 'src/example.ts' } });
const result = (id = 'call-1', value: unknown = 'file contents', extra: object = {}) => ({ type: 'tool_result', tool_use_id: id, content: value, ...extra });
const exported = (messages: unknown[], extra: object = {}) => JSON.stringify([{ uuid: 'claude-thread', name: 'Fixture conversation', created_at: at, chat_messages: messages, ...extra }]);
const user = (text: string) => ({ uuid: 'user-1', sender: 'human', text, created_at: at });
const assistant = (content: unknown[], extra: object = {}) => ({ uuid: 'assistant-1', sender: 'assistant', content, created_at: later, ...extra });
const code = (uuid: string, parentUuid: string | null, role: 'user' | 'assistant', content: unknown, extra: object = {}) => ({
  type: role, uuid, parentUuid, sessionId: 'session-1', timestamp: at, message: { role, content }, ...extra,
});
const jsonl = (rows: unknown[]) => rows.map((row) => JSON.stringify(row)).join('\n');
const meta = { timestamp: at, type: 'session_meta', payload: { id: 'codex-thread', timestamp: at, instructions: 'DO NOT IMPORT AS AUTHORITY', cwd: '/not/a/workspace' } };
const response = (payload: object, timestamp = at) => ({ timestamp, type: 'response_item', payload });
const message = (role: string, text: string) => response({ type: 'message', role, content: [{ type: role === 'assistant' ? 'output_text' : 'input_text', text }] });
const event = (type: string, message: string) => ({ timestamp: at, type: 'event_msg', payload: { type, message } });
const parse = (rows: unknown[]) => parseChatImport(jsonl(rows), 'fixture.jsonl');

test('Claude export preserves block text/tool offsets, ids, results and errors without executable metadata', () => {
  const parsed = parseChatImport(exported([
    user('Inspect the fixture.'),
    assistant([plain('Before '), { ...call(), approvalId: 'live-approval', activityId: 'live-activity', preview: { target: 'file:///secret' } }, plain('after')], { text: 'Before after', meta: { previews: ['file:///secret'] } }),
    { sender: 'human', content: [result('call-1', [plain('Not found')], { is_error: true })] },
  ]), 'conversations.json');
  assert.equal(parsed.conversations.length, 1);
  const conversation = parsed.conversations[0];
  assert.equal(conversation.source, 'claude');
  assert.equal(conversation.format, 'claude-export');
  assert.equal(conversation.externalId, 'claude-thread');
  assert.equal(conversation.createdAt, Date.parse(at));
  assert.equal(conversation.updatedAt, Date.parse(later));
  assert.equal(conversation.messages.length, 2, 'a result-only user transport record is not a human message');
  const answer = conversation.messages[1];
  assert.equal(answer.content, 'Before after', 'export text mirrors are not appended twice');
  const tool = answer.meta.tools![0];
  assert.equal(tool.callId, 'call-1');
  assert.equal(tool.contentOffset, 7);
  assert.equal(tool.status, 'failed');
  assert.equal(tool.result, 'Not found');
  assert.equal(tool.args, '{"path":"src/example.ts"}');
  assert.match(tool.caution!, /historical.*not executed/i);
  for (const property of ['approvalId', 'activityId', 'serverId', 'preview', 'subagent', 'awaitingApproval']) assert.equal(Object.hasOwn(tool, property), false);
  assert.equal(Object.hasOwn(conversation, 'directory'), false);
});

test('Claude export matches out-of-order tool results, including results that precede calls', () => {
  const parsed = parseChatImport(exported([
    { sender: 'human', content: [result('second', 'two'), result('first', 'one')] },
    assistant([plain('Look'), call('first'), plain(' again'), call('second')]),
  ]), 'conversations.json').conversations[0];
  assert.deepEqual(parsed.messages[0].meta.tools!.map(({ callId, result, contentOffset, status }) => ({ callId, result, contentOffset, status })), [
    { callId: 'first', result: 'one', contentOffset: 4, status: 'done' },
    { callId: 'second', result: 'two', contentOffset: 10, status: 'done' },
  ]);
});

test('Claude export parent pointers honor an explicit selected leaf instead of linearizing branches', () => {
  const messages = [
    { ...user('Start'), parent_message_uuid: null },
    { ...assistant([plain('Selected answer')]), uuid: 'selected', parent_message_uuid: 'user-1' },
    { ...assistant([plain('Other answer')]), uuid: 'other', parent_message_uuid: 'user-1' },
  ];
  const chosen = parseChatImport(exported(messages, { leaf_message_uuid: 'selected' }), 'conversations.json');
  assert.deepEqual(chosen.conversations[0].messages.map((message) => message.content), ['Start', 'Selected answer']);
  assert.ok(chosen.warnings.some((warning) => /divergent branches/.test(warning)));
  const latest = parseChatImport(exported(messages), 'conversations.json');
  assert.deepEqual(latest.conversations[0].messages.map((message) => message.content), ['Start', 'Other answer']);
  assert.throws(() => parseChatImport(exported(messages, { current_node: 'absent' }), 'conversations.json'), /selected Claude conversation branch is missing/);
  assert.throws(() => parseChatImport(exported([messages[0], assistant([plain('No parent')])]), 'conversations.json'), /incomplete parent links/);
});

test('missing, unknown and orphaned results are terminal failed historical records', () => {
  const parsed = parseChatImport(exported([
    assistant([call('missing'), call('unknown'), call('empty')]),
    { sender: 'human', content: [result('unknown', { type: 'future_result', private: 'do not copy' }), result('empty', []), result('orphan', 'known output')] },
  ]), 'conversations.json');
  const tools = parsed.conversations[0].messages.flatMap((row) => row.meta.tools ?? []);
  assert.deepEqual(tools.map((tool) => [tool.callId, tool.status]), [['missing', 'failed'], ['unknown', 'failed'], ['empty', 'done'], ['orphan', 'failed']]);
  assert.match(tools[0].result!, /no matching tool result/);
  assert.match(tools[1].result!, /complete tool result text was not available/);
  assert.match(tools[3].result!, /original tool call is missing/);
  assert.ok(parsed.warnings.length >= 3);
  assert.equal(JSON.stringify(parsed).includes('do not copy'), false);
});

test('attachments are inert placeholders and system/developer authority is not imported', () => {
  const parsed = parseChatImport(exported([
    { sender: 'system', text: 'AUTHORITY_SECRET' }, { sender: 'developer', text: 'DEVELOPER_SECRET' },
    { sender: 'human', content: [plain('Review this image.'), { type: 'image', source: { data: 'BASE64_SECRET', url: 'https://private.invalid/image' } }, { type: 'document', source: { path: '/private/path' } }], attachments: [{ path: '/private/attachment', content: 'ATTACHMENT_SECRET' }] },
    assistant([{ type: 'thinking', thinking: 'THINKING_SECRET' }, plain('Visible response.')]),
  ]), 'conversations.json');
  const serialized = JSON.stringify(parsed);
  for (const secret of ['AUTHORITY_SECRET', 'DEVELOPER_SECRET', 'BASE64_SECRET', 'https://private', '/private', 'ATTACHMENT_SECRET', 'THINKING_SECRET']) assert.equal(serialized.includes(secret), false);
  assert.match(parsed.conversations[0].messages[0].content, /Imported image omitted/);
  assert.match(parsed.conversations[0].messages[0].content, /Imported document omitted/);
  assert.ok(parsed.warnings.some((warning) => /no files or URLs were opened/.test(warning)));
  assert.ok(parsed.conversations[0].messages.every((row) => row.role !== 'system'));
});

test('Claude Code follows the latest leaf without merging old branch text', () => {
  const parsed = parse([
    code('u', null, 'user', 'Start'), code('a-old', 'u', 'assistant', [plain('Discarded branch')]),
    code('a-new', 'u', 'assistant', [plain('Selected branch'), call()]),
    code('r', 'a-new', 'user', [result()]), code('a-end', 'r', 'assistant', [plain('Finished')]),
  ]);
  assert.equal(parsed.conversations[0].format, 'claude-code');
  assert.equal(parsed.conversations[0].externalId, 'session-1');
  assert.deepEqual(parsed.conversations[0].messages.map((message) => message.content), ['Start', 'Selected branch\n\nFinished']);
  assert.equal(parsed.conversations[0].messages[1].meta.tools![0].result, 'file contents');
  assert.ok(parsed.warnings.some((warning) => /divergent branches/.test(warning)));
});

test('Claude sibling result records attach to selected calls without importing unrelated branch user text', () => {
  const parsed = parse([
    code('u', null, 'user', 'Start'), code('a', 'u', 'assistant', [call('one'), call('two')]),
    code('r1', 'a', 'user', [result('one', 'first result'), plain('OFF_BRANCH_SECRET')]),
    code('r2', 'a', 'user', [result('two', 'second result')]), code('end', 'r2', 'assistant', 'Done'),
  ]);
  const conversation = parsed.conversations[0];
  assert.equal(JSON.stringify(conversation).includes('OFF_BRANCH_SECRET'), false);
  assert.deepEqual(conversation.messages[1].meta.tools!.map((tool) => tool.result), ['first result', 'second result']);
});

test('Claude Code separates sessions and sidechains; absent parent links warn rather than inventing ancestry', () => {
  const rows = [code('u1', null, 'user', 'First'), code('u2', null, 'user', 'Second', { sessionId: 'session-2' }),
    code('sub', null, 'assistant', 'Subagent history', { isSidechain: true, agentId: 'child-1' })];
  const parsed = parse(rows);
  assert.equal(parsed.conversations.length, 3);
  assert.ok(parsed.warnings.some((warning) => /separately/.test(warning)));
  assert.ok(parsed.conversations.every((conversation) => conversation.messages.every((message) => !message.meta.tools?.some((tool) => tool.subagent))));
  const noLinks = parse([{ type: 'user', uuid: 'u', sessionId: 's', message: { role: 'user', content: 'Unlinked' } }]);
  assert.ok(noLinks.warnings.some((warning) => /no parent links/.test(warning)));
});

test('Claude parent-chain cycles, conflicting IDs and partial chain identities fail safely', () => {
  assert.throws(() => parse([code('u', 'a', 'user', 'One'), code('a', 'u', 'assistant', 'Two')]), /cycle/);
  assert.throws(() => parse([code('same', null, 'user', 'One'), code('same', null, 'user', 'Two')]), /Conflicting duplicate/);
  assert.throws(() => parse([code('u', null, 'user', 'One'), { type: 'assistant', message: { role: 'assistant', content: 'Two' } }]), /incomplete identifiers/);
  const orphan = parse([code('a', 'not-present', 'assistant', 'Available history')]);
  assert.ok(orphan.warnings.some((warning) => /missing parent/.test(warning)));
});

test('Codex canonical user/assistant response items suppress mirrored event messages', () => {
  const parsed = parse([meta, event('user_message', 'Start'), message('user', 'Start'),
    event('agent_message', 'Before'), message('assistant', 'Before'),
    response({ type: 'function_call', call_id: 'shell-1', name: 'exec_command', arguments: '{"cmd":"pwd"}' }),
    response({ type: 'function_call_output', call_id: 'shell-1', output: [{ type: 'input_text', text: '/fixture' }] }),
    message('assistant', 'After'), event('agent_message', 'After'),
  ]);
  const conversation = parsed.conversations[0];
  assert.equal(conversation.format, 'codex-rollout');
  assert.equal(conversation.externalId, 'codex-thread');
  assert.deepEqual(conversation.messages.map((message) => message.content), ['Start', 'Before\n\nAfter']);
  const tool = conversation.messages[1].meta.tools![0];
  assert.equal(tool.callId, 'shell-1');
  assert.equal(tool.contentOffset, 6);
  assert.equal(tool.result, '/fixture');
  assert.equal(tool.status, 'done');
  assert.equal(JSON.stringify(conversation).includes('DO NOT IMPORT AS AUTHORITY'), false);
});

test('Codex repeated prompts/answers in different turns are not collapsed', () => {
  const parsed = parse([meta, event('user_message', 'Again'), message('user', 'Again'), message('assistant', 'OK'), event('agent_message', 'OK'),
    event('user_message', 'Again'), message('user', 'Again'), event('agent_message', 'OK'), message('assistant', 'OK')]);
  assert.deepEqual(parsed.conversations[0].messages.map((message) => message.content), ['Again', 'OK', 'Again', 'OK']);
});

test('an older event-only utterance cannot steal a later identical canonical turn', () => {
  const parsed = parse([meta, event('user_message', 'Continue'), event('agent_message', 'OK'),
    message('user', 'Continue'), message('assistant', 'OK')]);
  assert.deepEqual(parsed.conversations[0].messages.map((message) => message.content), ['Continue', 'OK', 'Continue', 'OK']);
  const tools = parse([meta, message('user', 'Start'), event('agent_message', 'Checking'),
    response({ type: 'function_call', call_id: 'tool', name: 'read_file', arguments: '{}' }),
    response({ type: 'function_call_output', call_id: 'tool', output: 'Done' }), message('assistant', 'Checking')]);
  assert.equal(tools.conversations[0].messages[1].content, 'Checking\n\nChecking');
  assert.equal(tools.conversations[0].messages[1].meta.tools![0].contentOffset, 8);
});

test('Codex event-only turns are recoverable with an explicit warning', () => {
  const parsed = parse([meta, event('user_message', 'Canonical unavailable'), event('agent_message', 'Historical event answer')]);
  assert.deepEqual(parsed.conversations[0].messages.map((message) => message.content), ['Canonical unavailable', 'Historical event answer']);
  assert.ok(parsed.warnings.some((warning) => /event records/.test(warning)));
});

test('Codex canonical multimodal messages win over mirrored event attachment metadata', () => {
  const parsed = parse([meta,
    { type: 'event_msg', payload: { type: 'user_message', message: 'Inspect', images: ['data:ONE'], local_images: ['/private/path'] } },
    response({ type: 'message', role: 'user', content: [{ type: 'input_text', text: 'Inspect' }, { type: 'input_image', image_url: 'data:ONE' }] }),
    message('assistant', 'Done'),
  ]);
  assert.equal(parsed.conversations[0].messages.length, 2);
  assert.equal(parsed.conversations[0].messages[0].content.match(/Imported image omitted/g)?.length, 1);
  assert.equal(JSON.stringify(parsed).includes('/private/path'), false);
});

test('unknown content is visible as a placeholder and missing result bodies cannot become successful', () => {
  const parsed = parseChatImport(exported([{ sender: 'human', content: { type: 'future', data: 'SECRET' } }, assistant([call()]),
    { sender: 'human', content: [{ type: 'tool_result', tool_use_id: 'call-1' }] }]), 'test.json');
  assert.match(parsed.conversations[0].messages[0].content, /Unsupported imported content/);
  assert.equal(parsed.conversations[0].messages[1].meta.tools![0].status, 'failed');
  assert.equal(JSON.stringify(parsed).includes('SECRET'), false);
  assert.throws(() => parseChatImport(exported([assistant([call(), call()])]), 'test.json'), /Duplicate tool call identifiers/);
});

test('Codex custom calls, legacy shell calls and out-of-order outputs retain data only', () => {
  const parsed = parse([meta, message('user', 'Edit a fixture'),
    response({ type: 'custom_tool_call_output', call_id: 'patch-1', output: 'Patched' }),
    response({ type: 'custom_tool_call', call_id: 'patch-1', name: 'apply_patch', input: '*** patch text ***', status: 'completed' }),
    response({ type: 'local_shell_call', id: 'shell-legacy', call_id: null, action: { type: 'exec', command: ['pwd'], working_directory: '/fixture' }, status: 'in_progress' }),
    response({ type: 'function_call_output', call_id: 'shell-legacy', output: '/fixture' }),
    message('assistant', 'Finished'),
  ]);
  const tools = parsed.conversations[0].messages[1].meta.tools!;
  assert.deepEqual(tools.map((tool) => tool.status), ['done', 'done']);
  assert.equal(tools[0].args, '*** patch text ***');
  assert.equal(tools[1].callId, 'shell-legacy');
  assert.equal(tools[1].toolName, 'local_shell');
  assert.match(tools[1].args!, /"command":\["pwd"\]/);
});

test('Codex unsafe authority, hidden reasoning and attachment payloads do not cross into imported metadata', () => {
  const parsed = parse([meta, message('system', 'SYSTEM_SECRET'), message('developer', 'DEVELOPER_SECRET'),
    response({ type: 'message', role: 'user', content: [{ type: 'input_text', text: 'Look' }, { type: 'input_image', image_url: 'data:SECRET' }, { type: 'input_audio', audio_url: 'https://SECRET' }] }),
    response({ type: 'reasoning', encrypted_content: 'REASONING_SECRET', summary: [{ type: 'summary_text', text: 'HIDDEN_SECRET' }] }),
    response({ type: 'agent_message', author: 'hidden-agent', recipient: 'root', content: [{ type: 'input_text', text: 'AGENT_SECRET' }] }),
    message('assistant', 'Visible answer'),
  ]);
  assert.equal(JSON.stringify(parsed).includes('SECRET'), false);
  assert.ok(parsed.conversations[0].messages.every((message) => message.role !== 'system'));
  assert.match(parsed.conversations[0].messages[0].content, /image omitted.*\n.*audio omitted/);
});

test('Codex rollbacks and conflicting snapshots fail explicitly rather than splicing branches', () => {
  assert.throws(() => parse([meta, message('user', 'Start'), { type: 'event_msg', payload: { type: 'thread_rolled_back', num_turns: 1 } }]), /rollback edits/);
  assert.throws(() => parse([meta, response({ type: 'message', id: 'same', role: 'user', content: [{ type: 'input_text', text: 'One' }] }),
    response({ type: 'message', id: 'same', role: 'user', content: [{ type: 'input_text', text: 'Two' }] })]), /Conflicting Codex/);
});

test('canonical history formats are detected by schema, not the filename; prompt-only history is rejected', () => {
  assert.equal(parseChatImport(exported([user('Hello')]), 'unrelated-name.data').conversations[0].format, 'claude-export');
  assert.throws(() => parseChatImport(jsonl([{ session_id: 'private-id', ts: 1700000000, text: 'PRIVATE_PROMPT' }]), 'history.jsonl'), /prompt history, not a complete/);
  assert.throws(() => parse([meta, code('u', null, 'user', 'Mixed')]), /Mixed Claude and Codex/);
  assert.throws(() => parseChatImport('unexpected', 'conversations.json'), /Invalid JSON at line 1/);
  assert.throws(() => parseChatImport('', 'empty.json'), /empty/);
  assert.throws(() => parseChatImport(jsonl([meta]) + '\n{"SECRET_BAD_CONTENT":', 'fixture.jsonl'), (error: unknown) => error instanceof Error && /line 2/.test(error.message) && !error.message.includes('SECRET'));
});

test('imports are deterministic, accept BOM/CRLF, normalize timestamps and warn on shortened titles', () => {
  const input = '\uFEFF' + jsonl([meta, message('user', 'Hello')]).replaceAll('\n', '\r\n');
  assert.deepEqual(parseChatImport(input, 'one.jsonl'), parseChatImport(input, 'two.jsonl'));
  const parsed = parseChatImport(exported([user('Hello')], { name: 'A'.repeat(241), created_at: 1_700_000_000, updated_at: 'invalid' }), 'test.json');
  assert.equal(parsed.conversations[0].title.length, 240);
  assert.equal(parsed.conversations[0].createdAt, 1_700_000_000_000);
  assert.ok(parsed.warnings.some((warning) => /titles were shortened/.test(warning)));
  assert.ok(parsed.warnings.some((warning) => /invalid timestamps/.test(warning)));
});

test('oversized imports and record/message/tool limits fail instead of silently truncating', () => {
  assert.throws(() => parseChatImport('x'.repeat(32 * 1024 * 1024 + 1), 'large.json'), /32 MiB/);
  assert.throws(() => parseChatImport(exported([user('x'.repeat(16 * 1024 * 1024 + 1))]), 'large.json'), /16 MiB/);
  assert.throws(() => parseChatImport(JSON.stringify(Array.from({ length: 1001 }, () => ({ chat_messages: [] }))), 'many.json'), /1000-conversation/);
  assert.throws(() => parseChatImport(exported(Array.from({ length: 20_001 }, (_, index) => user(`Message ${index}`))), 'many.json'), /20,000-message/);
  assert.throws(() => parseChatImport(exported([assistant(Array.from({ length: 2001 }, (_, index) => call(`tool-${index}`)))]), 'tools.json'), /2000-tool/);
});
